import React, { useState, useEffect, useRef } from 'react';
import './index.css';

const App: React.FC = () => {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState<string[]>([]);
  const [booting, setBooting] = useState(true);
  const inputRef = useRef<HTMLInputElement>(null);

  const bootSequence = [
    'Booting up...',
    'Connecting to secure server...',
    'Connection established.',
    'Welcome to my terminal. Type `help` for a list of commands.',
  ];

  const bootedRef = useRef(false);

  useEffect(() => {
    if (booting && !bootedRef.current) {
      bootedRef.current = true;
      const boot = async () => {
        for (let i = 0; i < bootSequence.length; i++) {
          await new Promise((resolve) => setTimeout(resolve, 500));
          setOutput((prevOutput) => [...prevOutput, bootSequence[i]]);
        }
        setBooting(false);
      };
      boot();
    }
  }, [booting]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInput(e.target.value);
  };

  const handleInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !booting) {
      let newOutput = [...output, `> ${input}`];

      switch (input.toLowerCase()) {
        case 'help':
          newOutput.push('Available commands: help, about, projects, skills, contact, clear');
          break;
        case 'about':
          newOutput.push('I am a Computer Science major at Strathmore University, deeply passionate about cybersecurity, distributed systems, software development, and AI/ML. Outside of academics, I\'m an avid sportsman, actively involved in rugby and hitting the gym. My defining characteristic is grit; you could say it\'s my middle name.');
          break;
        case 'projects':
          newOutput.push('Here are some of my projects:');
          newOutput.push('- Project 1: A vulnerability assessment of a web application.');
          newOutput.push('- Project 2: A network security analysis of a corporate network.');
          newOutput.push('- Project 3: A malware analysis of a suspicious file.');
          break;
        case 'skills':
          newOutput.push('My skills include: Bash scripting, Server Administration, Python, Mobile App Development (Flutter), Cloud Computing (AWS, Azure), React, JavaScript.');
          break;
        case 'contact':
          newOutput.push('You can reach me at: [secure@email.com](mailto:secure@email.com)');
          break;
        case 'clear':
          newOutput = [...bootSequence];
          break;
        default:
          newOutput.push(`Command not found: ${input}`);
          break;
      }

      setOutput(newOutput);
      setInput('');
    }
  };

  useEffect(() => {
    if (!booting && inputRef.current) {
      inputRef.current.focus();
    }
  }, [booting]);

  return (
    <div className="container">
      <div className="output">
        {output.map((line, index) => (
          <div
            key={index}
            className={`line-reveal ${line.startsWith('>') ? 'command-color' : 'output-color'}
              ${line.startsWith('Command not found') ? 'error-color' : ''}
            `}
          >
            <span>{line}</span>
          </div>
        ))}
      </div>
      {!booting && (
        <div className="input-line">
          <span>&gt;</span>
          <input
            type="text"
            value={input}
            onChange={handleInputChange}
            onKeyDown={handleInputKeyDown}
            ref={inputRef}
            autoFocus
          />
          <span className="cursor"></span>
        </div>
      )}
    </div>
  );
};


export default App;
